<?php
namespace App\Modules\Orders\Application;
use App\Modules\Audit\Application\RecordAuditEvent;use App\Modules\Customers\Domain\Models\CustomerProfile;use App\Modules\Identity\Application\UseAuthorization;use App\Modules\Orders\Application\Data\SalesOrderData;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\Orders\Domain\Models\SalesOrder;use App\Modules\Pricing\Application\ResolvePrice;use App\Modules\Shared\Application\NextDocumentNumber;use DomainException;use Illuminate\Support\Facades\DB;
class SaveDraftOrder {public function __construct(private readonly ResolvePrice $prices,private readonly NextDocumentNumber $numbers,private readonly UseAuthorization $useAuthorization,private readonly RecordAuditEvent $audit){}
public function execute(SalesOrderData $data,?SalesOrder $order=null):SalesOrder{return DB::transaction(function()use($data,$order):SalesOrder{if($data->dueAt->lt($data->orderedAt))throw new DomainException('La entrega no puede ser anterior al pedido.');if($data->lines===[])throw new DomainException('El pedido debe tener productos.');$customer=CustomerProfile::query()->with('defaultPriceList')->where('is_active',true)->findOrFail($data->customerProfileId);if($order&&$order->status!==SalesOrderStatus::Draft)throw new DomainException('Solo se editan pedidos en borrador.');$before=$order?->load('lines')->toArray();$order??=SalesOrder::create(['document_number'=>$this->numbers->execute('sales_order','PED',$data->orderedAt),'customer_person_id'=>$customer->person_id,'ordered_at'=>$data->orderedAt,'due_at'=>$data->dueAt,'priority'=>$data->priority,'status'=>SalesOrderStatus::Draft,'price_list_id'=>$data->priceListId,'subtotal'=>0,'discount'=>0,'total'=>0,'advance_amount'=>0,'balance_amount'=>0,'created_by'=>$data->actor->id]);$order->lines()->delete();$subtotal=0;$usesAuthorization=false;
foreach($data->lines as $line){if(bccomp($line->quantity,'0',6)<=0)throw new DomainException('Las cantidades deben ser positivas.');$resolved=$this->prices->execute($line->presentationId,$customer,$data->priceListId,$data->orderedAt);$listed=$resolved['item'];$applied=$line->unitPrice??$listed->price;if($applied!==$listed->price&&!$data->actor->hasPermission('prices.override'))throw new DomainException('No tienes permiso para aplicar un precio personalizado.');$catalogMinimum=(int)($listed->presentation()->value('minimum_sale_price')??0);$minimum=max((int)($listed->minimum_price??0),$catalogMinimum);$lineUsesAuthorization=false;if($applied<$minimum){if(trim((string)$line->priceReason)==='')throw new DomainException('El precio inferior al mínimo requiere motivo.');$auth=$data->priceAuthorization;if(!$order->exists||!$auth?->isUsable()||$auth->approval_permission!=='prices.authorize-below-minimum'||$auth->resource_type!==$order->getMorphClass()||(string)$auth->resource_id!==(string)$order->id)throw new DomainException('El precio inferior al mínimo requiere autorización vigente para este pedido.');$usesAuthorization=true;$lineUsesAuthorization=true;}$gross=(int)round((float)$line->quantity*$applied);if($line->discount<0||$line->discount>$gross)throw new DomainException('El descuento de línea no es válido.');$total=$gross-$line->discount;$subtotal+=$total;$order->lines()->create(['presentation_id'=>$line->presentationId,'price_list_item_id'=>$listed->id,'ordered_quantity'=>$line->quantity,'list_unit_price'=>$listed->price,'unit_price'=>$applied,'discount'=>$line->discount,'line_total'=>$total,'price_reason'=>$line->priceReason,'price_authorization_id'=>$lineUsesAuthorization?$data->priceAuthorization?->id:null,'notes'=>$line->notes]);}
if($data->discount<0||$data->discount>$subtotal)throw new DomainException('El descuento general no es válido.');$total=$subtotal-$data->discount;if($order->advance_amount>$total)throw new DomainException('El total no puede quedar por debajo de los anticipos recibidos.');$order->update(['customer_person_id'=>$customer->person_id,'ordered_at'=>$data->orderedAt,'due_at'=>$data->dueAt,'priority'=>$data->priority,'price_list_id'=>$data->priceListId,'subtotal'=>$subtotal,'discount'=>$data->discount,'total'=>$total,'balance_amount'=>$total-$order->advance_amount,'notes'=>$data->notes]);if($usesAuthorization)$this->useAuthorization->execute($data->priceAuthorization);$this->audit->execute($before?'orders.draft_updated':'orders.draft_created',$order,$data->actor,before:$before,after:$order->fresh('lines')->toArray(),authorizationRequestId:$usesAuthorization?$data->priceAuthorization?->id:null);return $order->fresh('lines');});}}
